+import { test, expect } from "@playwright/test";
+import {
+  AUTOSAVE_STORAGE_KEY,
+  parseAutosaveSnapshot,
+  readAutosaveSnapshot,
+  writeAutosaveSnapshot,
+  clearAutosaveSnapshot,
